import{_ as l,a0 as t,w as d,s as o,ao as r,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"掌握 Linux 用户组 | LCTT x X-CMD","titleTemplate":false,"description":"掌握 Linux 用户组 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"掌握 Linux 用户组 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"掌握 Linux 用户组 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190717 Mastering user groups on Linux","title":"掌握 Linux 用户组","tag":"201907","desc":""},"relativePath":"201907/20190717 Mastering user groups on Linux.md","filePath":"[post].md"}'),c={name:"201907/20190717 Mastering user groups on Linux.md"};function h(g,s,u,b,k,f){const n=t("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="掌握-linux-用户组" tabindex="-1">掌握 Linux 用户组 <a class="header-anchor" href="#掌握-linux-用户组" aria-label="Permalink to “掌握 Linux 用户组”">​</a></h1><blockquote><p>在 Linux 系统中管理用户组并不费力，但相关命令可能比你所知的更为灵活。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/07/carrots-100801917-large.jpg" alt="Scott 97006 CC BY 2.0"></p><p>在 Linux 系统中用户组起着重要作用。用户组提供了一种简单方法供一组用户互相共享文件。用户组也允许系统管理员更加有效地管理用户权限，因为管理员可以将权限分配给用户组而不是逐一分配给单个用户。</p><p>尽管通常只要在系统中添加用户账户就会创建用户组，关于用户组如何工作以及如何运用用户组还有很多需要了解的。</p><h3 id="一个用户一个用户组" tabindex="-1">一个用户一个用户组？ <a class="header-anchor" href="#一个用户一个用户组" aria-label="Permalink to “一个用户一个用户组？”">​</a></h3><p>Linux 系统中多数用户账户被设为用户名与用户组名相同。用户 <code>jdoe</code> 会被赋予一个名为 <code>jdoe</code> 的用户组，且成为该新建用户组的唯一成员。如本例所示，该用户的登录名，用户 id 和用户组 id 在新建账户时会被添加到 <code>/etc/passwd</code> 和 <code>/etc/group</code> 文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd jdoe</span></span>
<span class="line"><span>$ grep jdoe /etc/passwd</span></span>
<span class="line"><span>jdoe:x:1066:1066:Jane Doe:/home/jdoe:/bin/sh</span></span>
<span class="line"><span>$ grep jdoe /etc/group</span></span>
<span class="line"><span>jdoe:x:1066:</span></span></code></pre></div><p>这些文件中的配置使系统得以在文本（<code>jdoe</code>）和数字（<code>1066</code>）这两种用户 id 形式之间互相转换—— <code>jdoe</code> 就是 <code>1006</code>，且 <code>1006</code> 就是 <code>jdoe</code>。</p><p>分配给每个用户的 UID（用户 id）和 GID（用户组 id）通常是一样的，并且顺序递增。若上例中 Jane Doe 是最近添加的用户，分配给下一个新用户的用户 id 和用户组 id 很可能都是 1067。</p><h3 id="gid-uid" tabindex="-1">GID = UID？ <a class="header-anchor" href="#gid-uid" aria-label="Permalink to “GID = UID？”">​</a></h3><p>UID 和 GID 可能不一致。例如，如果你用 <code>groupadd</code> 命令添加一个用户组而不指定用户组 id，系统会分配下一个可用的用户组 id（在本例中为 1067）。下一个添加到系统中的用户其 UID 会是 1067 而 GID 则为 1068。</p><p>你可以避免这个问题，方法是添加用户组的时候指定一个较小的用户组 id 而不是接受默认值。在下面的命令中我们添加一个用户组并提供一个 GID，这个 GID 小于用于用户账户的 GID 取值范围。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo groupadd -g 500 devops</span></span></code></pre></div><p>创建账户时你可以指定一个共享用户组，如果这样对你更合适的话。例如你可能想把新来的开发人员加入同一个 DevOps 用户组而不是一人一个用户组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd -g staff bennyg</span></span>
<span class="line"><span>$ grep bennyg /etc/passwd</span></span>
<span class="line"><span>bennyg:x:1064:50::/home/bennyg:/bin/sh</span></span></code></pre></div><h3 id="主要用户组和次要用户组" tabindex="-1">主要用户组和次要用户组 <a class="header-anchor" href="#主要用户组和次要用户组" aria-label="Permalink to “主要用户组和次要用户组”">​</a></h3><p>用户组实际上有两种：<ruby>主要用户组<rt>primary group</rt></ruby>和<ruby>次要用户组<rt>secondary group</rt></ruby>。</p><p>主要用户组是保存在 <code>/etc/passwd</code> 文件中的用户组，该用户组在账户创建时配置。当用户创建一个文件时，用户的主要用户组与此文件关联。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ whoami</span></span>
<span class="line"><span>jdoe</span></span>
<span class="line"><span>$ grep jdoe /etc/passwd</span></span>
<span class="line"><span>jdoe:x:1066:1066:John Doe:/home/jdoe:/bin/bash</span></span>
<span class="line"><span>             ^</span></span>
<span class="line"><span>             |</span></span>
<span class="line"><span>             +-------- 主要用户组</span></span>
<span class="line"><span>$ touch newfile</span></span>
<span class="line"><span>$ ls -l newfile</span></span>
<span class="line"><span>-rw-rw-r-- 1 jdoe jdoe 0 Jul 16 15:22 newfile</span></span>
<span class="line"><span>                   ^</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>                   +-------- 主要用户组</span></span></code></pre></div><p>用户一旦拥有账户之后被加入的那些用户组是次要用户组。次要用户组成员关系在 <code>/etc/group</code> 文件中显示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep devops /etc/group</span></span>
<span class="line"><span>devops:x:500:shs,jadep</span></span>
<span class="line"><span>          ^</span></span>
<span class="line"><span>          |</span></span>
<span class="line"><span>          +-------- shs 和 jadep 的次要用户组</span></span></code></pre></div><p><code>/etc/group</code> 文件给用户组分配组名称（例如 <code>500</code> = <code>devops</code>）并记录次要用户组成员。</p><h3 id="首选的准则" tabindex="-1">首选的准则 <a class="header-anchor" href="#首选的准则" aria-label="Permalink to “首选的准则”">​</a></h3><p>每个用户是他自己的主要用户组成员，并可以成为任意多个次要用户组成员，这样的一种准则允许用户更加容易地将个人文件和需要与同事分享的文件分开。当用户创建一个文件时，用户所属的不同用户组的成员不一定有访问权限。用户必须用 <code>chgrp</code> 命令将文件和次要用户组关联起来。</p><h3 id="哪里也不如自己的家目录" tabindex="-1">哪里也不如自己的家目录 <a class="header-anchor" href="#哪里也不如自己的家目录" aria-label="Permalink to “哪里也不如自己的家目录”">​</a></h3><p>添加新账户时一个重要的细节是 <code>useradd</code> 命令并不一定为新用户添加一个<ruby>家目录<rt>/home</rt></ruby>家目录。若你只有某些时候想为用户添加家目录，你可以在 <code>useradd</code> 命令中加入 <code>-m</code> 选项（可以把它想象成“安家”选项）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo useradd -m -g devops -c &quot;John Doe&quot; jdoe2</span></span></code></pre></div><p>此命令中的选项如下：</p><ul><li><code>-m</code> 创建家目录并在其中生成初始文件</li><li><code>-g</code> 指定用户归属的用户组</li><li><code>-c</code> 添加账户描述信息（通常是用户的姓名）</li></ul><p>若你希望总是创建家目录，你可以编辑 <code>/etc/login.defs</code> 文件来更改默认工作方式。更改或添加 <code>CREATE_HOME</code> 变量并将其设置为 <code>yes</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep CREATE_HOME /etc/login.defs</span></span>
<span class="line"><span>CREATE_HOME     yes</span></span></code></pre></div><p>另一种方法是用自己的账户设置别名从而让 <code>useradd</code> 一直带有 <code>-m</code> 选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ alias useradd=’useradd -m’</span></span></code></pre></div><p>确保将该别名添加到你的 <code>~/.bashrc</code> 文件或类似的启动文件中以使其永久生效。</p><h3 id="深入了解-etc-login-defs" tabindex="-1">深入了解 /etc/login.defs <a class="header-anchor" href="#深入了解-etc-login-defs" aria-label="Permalink to “深入了解 /etc/login.defs”">​</a></h3><p>下面这个命令可列出 <code>/etc/login.defs</code> 文件中的全部设置。下面的 <code>grep</code> 命令会隐藏所有注释和空行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/login.defs | grep -v &quot;^#&quot; | grep -v &quot;^$&quot;</span></span>
<span class="line"><span>MAIL_DIR        /var/mail</span></span>
<span class="line"><span>FAILLOG_ENAB            yes</span></span>
<span class="line"><span>LOG_UNKFAIL_ENAB        no</span></span>
<span class="line"><span>LOG_OK_LOGINS           no</span></span>
<span class="line"><span>SYSLOG_SU_ENAB          yes</span></span>
<span class="line"><span>SYSLOG_SG_ENAB          yes</span></span>
<span class="line"><span>FTMP_FILE       /var/log/btmp</span></span>
<span class="line"><span>SU_NAME         su</span></span>
<span class="line"><span>HUSHLOGIN_FILE  .hushlogin</span></span>
<span class="line"><span>ENV_SUPATH      PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin</span></span>
<span class="line"><span>ENV_PATH        PATH=/usr/local/bin:/usr/bin:/bin:/usr/local/games:/usr/games</span></span>
<span class="line"><span>TTYGROUP        tty</span></span>
<span class="line"><span>TTYPERM         0600</span></span>
<span class="line"><span>ERASECHAR       0177</span></span>
<span class="line"><span>KILLCHAR        025</span></span>
<span class="line"><span>UMASK           022</span></span>
<span class="line"><span>PASS_MAX_DAYS   99999</span></span>
<span class="line"><span>PASS_MIN_DAYS   0</span></span>
<span class="line"><span>PASS_WARN_AGE   7</span></span>
<span class="line"><span>UID_MIN                  1000</span></span>
<span class="line"><span>UID_MAX                 60000</span></span>
<span class="line"><span>GID_MIN                  1000</span></span>
<span class="line"><span>GID_MAX                 60000</span></span>
<span class="line"><span>LOGIN_RETRIES           5</span></span>
<span class="line"><span>LOGIN_TIMEOUT           60</span></span>
<span class="line"><span>CHFN_RESTRICT           rwh</span></span>
<span class="line"><span>DEFAULT_HOME    yes</span></span>
<span class="line"><span>CREATE_HOME         yes                 &lt;===</span></span>
<span class="line"><span>USERGROUPS_ENAB yes</span></span>
<span class="line"><span>ENCRYPT_METHOD SHA512</span></span></code></pre></div><p>注意此文件中的各种设置会决定用户 id 的取值范围以及密码使用期限和其他设置（如 umask）。</p><h3 id="如何显示用户所属的用户组" tabindex="-1">如何显示用户所属的用户组 <a class="header-anchor" href="#如何显示用户所属的用户组" aria-label="Permalink to “如何显示用户所属的用户组”">​</a></h3><p>出于各种原因用户可能是多个用户组的成员。用户组成员身份给与用户对用户组拥有的文件和目录的访问权限，有时候这种工作方式是至关重要的。要生成某个用户所属用户组的清单，用 <code>groups</code> 命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ groups jdoe</span></span>
<span class="line"><span>jdoe : jdoe adm admin cdrom sudo dip plugdev lpadmin staff sambashare</span></span></code></pre></div><p>你可以键入不带任何参数的 <code>groups</code> 命令来列出你自己的用户组。</p><h3 id="如何添加用户至用户组" tabindex="-1">如何添加用户至用户组 <a class="header-anchor" href="#如何添加用户至用户组" aria-label="Permalink to “如何添加用户至用户组”">​</a></h3><p>如果你想添加一个已有用户至别的用户组，你可以仿照下面的命令操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G devops jdoe</span></span></code></pre></div><p>你也可以指定逗号分隔的用户组列表来添加一个用户至多个用户组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G devops,mgrs jdoe</span></span></code></pre></div><p>参数 <code>-a</code> 意思是“添加”，<code>-G</code> 指定用户组列表。</p><p>你可以编辑 <code>/etc/group</code> 文件将用户名从用户组成员名单中删除，从而将用户从用户组中移除。<code>usermod</code> 命令或许也有个选项用于从用户组中删除某个成员。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fish:x:16:nemo,dory,shark</span></span>
<span class="line"><span>           |</span></span>
<span class="line"><span>           V</span></span>
<span class="line"><span>fish:x:16:nemo,dory</span></span></code></pre></div><h3 id="提要" tabindex="-1">提要 <a class="header-anchor" href="#提要" aria-label="Permalink to “提要”">​</a></h3><p>添加和管理用户组并非特别困难，但长远来看配置账户时的一致性可使这项工作更容易些。</p><hr>`,54)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3409781/mastering-user-groups-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3409781/mastering-user-groups-on-linux.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/0x996"},{default:i(()=>[...s[4]||(s[4]=[a("0x996",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const C=l(c,[["render",h]]);export{x as __pageData,C as default};
